#!/usr/bin/env node
/**
 * tred-allure.mjs — la nouvelle allure, et la piece vide qui se remplit.
 *
 *   LiquidTabBar     barre flottante, pastille qui GLISSE d'un onglet a
 *                    l'autre, libelle seulement sous l'onglet actif
 *   TredCompanion    le compagnon : le T du logo, avec des yeux qui
 *                    clignent a intervalle irregulier. Bati sur TA marque,
 *                    pas sur le blob violet de Knowunity
 *   ChatWelcome      l'accueil : compagnon + quatre pastilles d'intention
 *                    (resoudre, deposer, s'entrainer, Klausur) + le champ
 *   EmptyStart       sur le tableau de bord web : choisir ses cours quand
 *                    on n'a ni cours ni document
 *
 * Zero dependance ajoutee : Animated et react-native-svg etaient deja la.
 *
 * Contient aussi tout ce qui precede : bibliotheque de cours, schemas
 * circuitikz, tuteur qui reflechit et cherche.
 *
 * Verifie : tsc 0 (web + mobile), oxlint 0, bun test 155/155, vite build,
 * expo export android.
 *
 *   node tred-allure.mjs
 */
import { writeFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = resolve(depart);
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const parent = dirname(d);
      if (parent === d) break;
      d = parent;
    }
  }
  return null;
}

const R = racine();
if (!R) {
  console.error("Depot introuvable. Lance-le depuis C:\\dev\\tred-rdm\\aerostudy-ai.");
  process.exit(1);
}
console.log("Depot :", R, "\n");

const PAYLOAD = "";

const LOT = JSON.parse(inflateSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));
let n = 0;
for (const [chemin, b64] of Object.entries(LOT.ecrire)) {
  const cible = join(R, chemin);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  n++;
}
for (const chemin of LOT.supprimer) {
  const cible = join(R, chemin);
  if (existsSync(cible)) rmSync(cible);
}

console.log(`${n} fichiers poses.\n`);
console.log("1) La base, si ce n'est pas deja fait :");
console.log("     node migre-cours.mjs");
console.log("\n2) Voir la barre et le compagnon TOUT DE SUITE, sans deployer :");
console.log("     cd packages/mobile");
console.log("     node ../../node_modules/.bin/expo start");
console.log("     puis ouvre Expo Go sur ton telephone");
console.log("\n3) L'envoi (premiere construction : +4 a 6 min, TeX Live) :");
console.log("     git add -A");
console.log("     git commit -m \"barre flottante, compagnon, bibliotheque de cours\"");
console.log("     git push");
